{
  "status": "SUPPORTED",
  "task_summary": "Find a part, attach it to the object on the table, and put the tool back on the table.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "target_assembly",
        "entity_kind": "OBJECT",
        "function": "The object on the table that needs to be secured.",
        "required_count": 1
      ,
      "binding_policy": "DISTINCT",
      "candidate_categories": ["assembly", "device", "object"],
      "required_properties": ["needs_fastening"]
      },
      {
        "id": "compatible_part",
        "entity_kind": "OBJECT",
        "function": "A component that fits the target assembly to enable fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["part", "piece", "component"],
        "required_properties": ["fits_target", "secureable"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The instrument used to perform the fastening operation.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["wrench", "screwdriver", "gripper"],
        "required_properties": ["capable_of_fastening"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The flat surface where equipment is left after use.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "bench", "surface"],
        "required_properties": ["flat_surface", "stable"]
      }
    ],
    "functional_relations": [
      {
        "id": "part_suitable_for_target",
        "relation": "compatible_with",
        "participant_roles": [
          "compatible_part",
          "target_assembly"
        ]
      ,
        "required": true
      },
      {
        "id": "part_attached_to_target",
        "relation": "secured_to",
        "participant_roles": [
          "compatible_part",
          "target_assembly"
        ]
      ,
        "required": true
      },
      {
        "id": "tool_left_on_bench",
        "relation": "placed_on",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "find_and_select_part",
        "operation": "identify_compatible_component",
        "participant_roles": [
          "compatible_part",
          "target_assembly"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "attach_component",
        "participant_roles": [
          "compatible_part",
          "target_assembly",
          "fastening_tool"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "return_tool",
        "operation": "place_equipment",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "target_assembly": [
        {
          "label": "black_tray_with_yellow_blue_parts",
          "visual_description": "A black rectangular tray sitting on the wooden table containing yellow and blue blocks."
        }
      ],
      "compatible_part": [],
      "fastening_tool": [
        {
          "label": "robot_gripper_yellow",
          "visual_description": "A yellow gripper mechanism attached to the robot arm visible in the third image."
        }
      ],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "A light brown wooden desk with drawers underneath."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "upper_cabinet",
        "label": "blue_cabinet",
        "visual_description": "A tall blue cabinet standing against the wall behind the table.",
        "reason": "Closed storage structure that may contain compatible components or tools."
      },
      {
        "id": "lower_drawers",
        "label": "table_drawers",
        "visual_description": "Two blue drawers located underneath the table.",
        "reason": "Closed storage structures that may contain compatible components or tools."
      }
    ],
    "inspection_order": [
      "upper_cabinet",
      "lower_drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
